App.boot({id:'settings',title:'Settings',noCtx:true,render(el){const {esc,icon}=U,S=Store,db=S.db,u=App.user();
 el.innerHTML=`<div class="grid g2"><div class="card"><div class="card-head"><h3>Appearance & language</h3></div><div class="form-grid">${U.field({name:'theme',label:'Theme',options:[['light','Light'],['dark','Dark']],value:db.settings.theme})}${U.field({name:'lang',label:'Menu language',options:[['en','English'],['ur','اردو'],['sd','سنڌي']],value:db.settings.language})}</div><p class="hint">English / Urdu / Sindhi menu labels. Hari ledger statements are always printed in Sindhi.</p></div>
 <div class="card"><div class="card-head"><h3>My account</h3></div><ul class="list"><li><b style="width:110px">Name</b>${esc(u.name)}</li><li><b style="width:110px">Username</b>@${esc(u.username)}</li><li><b style="width:110px">Role</b>${esc(S.ROLES[u.role])}</li><li><b style="width:110px">Farm</b>${esc(u.farm||'All farms')}</li></ul></div>
 <div class="card"><div class="card-head"><h3>Demo access</h3></div><p>Farm staff can see only their assigned farm in this role preview. Real farm restrictions require secure server login and database policies.</p><p><b>Roles:</b> Owner, Office, Supervisor, Accountant. Kamdar has no login.</p><p><b>Approval:</b> Farm entries show immediately, office approves in bulk.</p><div class="alert">${icon('alert')}<span><b>Data:</b> Stored only in this browser. Do not enter real passwords or sensitive financial records.</span></div></div>
 <div class="card"><div class="card-head"><h3>Data backup</h3></div><p class="muted">Export everything to a JSON file, restore from a backup, or reset to the original sample data.</p><div class="row"><button class="btn" id="exp">${icon('download')} Export demo JSON backup</button><label class="btn secondary" style="margin:0">${icon('upload')} Import backup<input type="file" id="imp" accept="application/json" class="hide"></label>${App.isOffice()?`<button class="btn danger" id="rst">Reset demo data</button>`:''}</div></div></div>`;
 el.querySelector('[name=theme]').onchange=e=>{db.settings.theme=e.target.value;S.save();App.applyTheme();App.refresh()};
 el.querySelector('[name=lang]').onchange=e=>{db.settings.language=e.target.value;S.save();App.refresh()};
 document.getElementById('exp').onclick=()=>{const b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='farm-erp-demo-backup.json';a.click();URL.revokeObjectURL(a.href);S.log('Exported JSON backup');U.toast('Backup downloaded')};
 document.getElementById('imp').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.users)||!Array.isArray(d.farms))throw Error('Not a ZAZ ERP backup');if(!await U.confirmBox('Replace all current demo data with this backup?',{ok:'Import'}))return;S.db=d;S.save();S.log('Imported JSON backup');U.toast('Backup imported');App.refresh()}catch(err){U.toast(err.message,'error')}};r.readAsText(f)};
 const rs=document.getElementById('rst');if(rs)rs.onclick=async()=>{if(!await U.confirmBox('Reset all demo employees, farms, ledgers and audit history?',{ok:'Reset demo'}))return;S.reset();location.href='index.html'}}});
